function generateOrderSerial() {
  const prefix = "WG";
  const ts = Date.now().toString(36).toUpperCase();
  const rand = Math.random().toString(36).substring(2, 6).toUpperCase();
  return `${prefix}-${ts}-${rand}`;
}

function sendOrderEmailFallback(orderData) {
  const subject = encodeURIComponent(`[╪╖┘ä╪¿ ╪¼╪»┘è╪»] ${orderData.service} ΓÇö ${orderData.serial}`);
  const body = encodeURIComponent(
    `╪╖┘ä╪¿ ╪«╪»┘à╪⌐ ╪¼╪»┘è╪»\n\n╪º┘ä╪│┘è╪▒┘è╪º┘ä: ${orderData.serial}\n╪º┘ä╪«╪»┘à╪⌐: ${orderData.service}\n╪º┘ä╪º╪│┘à: ${orderData.name}\n╪º┘ä┘ç╪º╪¬┘ü: ${orderData.phone}\n╪º┘ä╪¿╪▒┘è╪»: ${orderData.email}\n╪º┘ä╪»┘ê┘ä╪⌐: ${orderData.country}\n╪º┘ä┘à╪»┘è┘å╪⌐: ${orderData.city}\n╪╖╪▒┘è┘é╪⌐ ╪º┘ä╪»┘ü╪╣: ${orderData.paymentMethod}\n╪¬╪º╪▒┘è╪« ╪º┘ä╪╖┘ä╪¿: ${orderData.dateStr}\n`
  );
  window.open(`mailto:${ADMIN_EMAIL}?subject=${subject}&body=${body}`, "_blank");
}

