                <input style={inputStyle} value={form.name} placeholder={isAr?"┘à╪¡┘à╪» ╪ú╪¡┘à╪» ╪º┘ä╪│┘è╪»":"Mohamed Ahmed"} onChange={e=>upd("name",e.target.value)} />
