              <div style={{ fontSize:11, color:t.subText, marginTop:4 }}>{selectedService?.billingLabel || (isAr?"╪»┘ü╪╣╪⌐ ┘ê╪º╪¡╪»╪⌐":"One-time payment")}</div>
