                          <label htmlFor={`curr-${exp.id}`} style={{ ...labelStyle, marginBottom:0, cursor:"pointer" }}>{lang==="ar" ? "╪ú╪╣┘à┘ä ┘ç┘å╪º ╪¡╪º┘ä┘è╪º┘ï" : "Currently working here"}</label>
